(7705332, 1265236, 67258, '<td valign="top">Pleasingly composed.</td>', 'Pleasingly composed.', '2021-11-02 06:05:04.000000', NULL, 1),
(7705333, 1264958, 67258, '<td valign="top">I do like playing with in camera movement.  This one is interesting but doesn''t quite work for me - entirely subjective, but I might prefer it if the movement was vertical rather than slanted.</td>', 'I do like playing with in camera movement.  This one is interesting but doesn''t quite work for me - entirely subjective, but I might prefer it if the movement was vertical rather than slanted.', '2021-11-02 06:06:14.000000', NULL, 1),
