(7705336, 1265221, 67258, '<td valign="top">A very pleasing scene, carefully composed.  The range of tones and colours is lovely.</td>', 'A very pleasing scene, carefully composed.  The range of tones and colours is lovely.', '2021-11-02 06:07:50.000000', NULL, 1),
(7705337, 1264947, 67258, '<td valign="top">This might be a case where focus stacking would be beneficial.  I do find the out of focus foreground leaves distracting.</td>', 'This might be a case where focus stacking would be beneficial.  I do find the out of focus foreground leaves distracting.', '2021-11-02 06:09:09.000000', NULL, 1),
